INSERT INTO feature VALUES('ci-budget-report','workflow','Each workflow''s runs timed whole against its hosted budget','lane-budgets','implemented','ordinary',NULL,'The nightly lane-budget report times every active workflow''s newest completed runs, wall time and the sum of their completed jobs'' times, with the Actions cache''s usage; `--summed NAME=BUDGET/CEILING` holds a workflow''s median sum to its budget and every run to its ceiling, names the job that grew in a run past the ceiling, and keeps the one budget issue open while over.','workflow-lane-budget','crates/workflow-lane-budget/tests/cli.rs',NULL,NULL);
